-- Development-only sample data. All passwords below are: salasana
create temporary table demo_users (id uuid, email text, first_name text, last_name text, gender text, skill_level text) on commit drop;

select id, 'authenticated', 'authenticated', email, crypt('salasana', gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}', jsonb_build_object('first_name', first_name, 'last_name', last_name, 'gender', gender, 'skill_level', skill_level), now(), now()
from demo_users
on conflict (id) do update set encrypted_password = excluded.encrypted_password, email_confirmed_at = now(), updated_at = now();

select id, first_name, last_name, email, gender, skill_level, 'user' from demo_users
on conflict (id) do update set first_name = excluded.first_name, last_name = excluded.last_name, email = excluded.email, gender = excluded.gender, skill_level = excluded.skill_level;

on conflict (id) do nothing;

on conflict (id) do nothing;

select id, captain_id, true from public.teams where league_id = '21000000-0000-0000-0000-000000000002'
on conflict (team_id, user_id) do update set is_captain = true;

on conflict (team_id, user_id) do nothing;

on conflict (id) do nothing;

on conflict (group_id, team_id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;